const notas = [
  "Entregaron las cajas en el depósito de Avellaneda. Cadena de frío cortada.",
  "El cliente no estaba. Se reprogramó la entrega de las cajas.",
  "Cajas golpeadas en la recepción. El remito quedó sin firma.",
  "Entrega conforme: pallet con frío y cadena de custodia al día.",
  "Llovía fuerte y la entrega se hizo en la puerta, con las cajas tapadas.",
  "Cadena de frío cortada, cadena de frío rota: se cortó la cadena en el camión.",
];
const vacias = new Set(["de","el","la","las","en","se","y","con","no","al","sin","del","los","un","una","que"]);
const sufijos = ["aron","as","es","a","s","o"];            // un «stemmer» de juguete, NO es Snowball
const raiz = (p) => { for (const s of sufijos) if (p.endsWith(s) && p.length - s.length >= 3) return p.slice(0, -s.length); return p; };
function tokenizar(texto) {
  return texto.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "")  // sin tildes
    .split(/[^a-zñ0-9]+/).filter((p) => p && !vacias.has(p)).map(raiz);
}
// 1) construir el índice invertido: término -> lista de [documento, veces]
const indice = new Map(); const largo = [];
notas.forEach((n, d) => {
  const ts = tokenizar(n); largo[d] = ts.length;
  const cuenta = new Map(); ts.forEach((t) => cuenta.set(t, (cuenta.get(t) || 0) + 1));
  for (const [t, f] of cuenta) { if (!indice.has(t)) indice.set(t, []); indice.get(t).push([d, f]); }
});
console.log("términos en el índice:", indice.size);
for (const t of ["caden", "fri", "entreg", "caj"]) console.log(t.padEnd(7), JSON.stringify(indice.get(t)));
// 2) buscar «cadena Y frío»: intersección de dos listas ordenadas
function interseccion(a, b) { const r = []; let i = 0, j = 0;
  while (i < a.length && j < b.length) { if (a[i][0] === b[j][0]) { r.push(a[i][0]); i++; j++; } else if (a[i][0] < b[j][0]) i++; else j++; }
  return r; }
console.log("cadena Y frío ->", interseccion(indice.get("caden"), indice.get("fri")).map((d) => d + 1));
// 3) ordenar por BM25 (k1 = 1,2; b = 0,75; idf como en Lucene)
const N = notas.length, prom = largo.reduce((a, b) => a + b) / N, k1 = 1.2, b = 0.75;
const idf = (n) => Math.log(1 + (N - n + 0.5) / (n + 0.5));
function bm25(consulta) {
  const punt = new Map();
  for (const t of tokenizar(consulta)) {
    const lista = indice.get(t) || [];
    for (const [d, f] of lista) punt.set(d, (punt.get(d) || 0) + idf(lista.length) * f / (f + k1 * (1 - b + b * largo[d] / prom)));
  }
  return [...punt].sort((x, y) => y[1] - x[1]);
}
console.log("largo promedio:", prom.toFixed(2), "| largos:", largo.join(","));
for (const [d, p] of bm25("cadena frío")) console.log("nota", d + 1, p.toFixed(3));
console.log("idf(caden)=", idf(indice.get("caden").length).toFixed(3), " idf(fri)=", idf(indice.get("fri").length).toFixed(3));

// Lo que hace buscar() de src/datos/biblia.ts, sobre la RV1909 de assets/biblia/, en solo lectura
const fs = require("fs");
const plegar = (s) => s.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ñ/g, "n");
const normalizar = (s) => plegar(s.toLowerCase()).replace(/[^a-z0-9ñ ]/g, " ");
const b = JSON.parse(fs.readFileSync(".../senda-app/assets/biblia/rv1909.bib", "utf8"));
const idx = [];                                        // un registro por versículo, con su texto ya normalizado
for (const l of b.libros) l.caps.forEach((c, ci) => c.forEach((v, vi) => {
  if (v) idx.push({ libro: l.id, cap: ci + 1, vers: vi + 1, texto: v, norm: ` ${normalizar(v)} ` });
}));
function buscar(consulta, max = 60) {
  const palabras = normalizar(consulta).split(/\s+/).filter((w) => w.length > 1);
  const claves = palabras.map((w) => (w.length <= 3 ? ` ${w} ` : ` ${w}`));   // cortas: palabra entera; largas: prefijo
  let total = 0; const lista = [];
  for (const v of idx) if (claves.every((w) => v.norm.includes(w))) { total++; if (lista.length < max) lista.push(v); }
  return { total, lista };
}
